tail -30 classic/apps/web/src/app/projects/store.ts; cat >> classic/apps/web/src/export/queue/server.test.ts <<'EOF'

test("direct destinations are claimed explicitly and never consumed by a background queue window",async()=>{
 for(const job of (await readRenderQueue()).jobs.filter(j=>j.status==="queued")) {
  const state=await readRenderQueue();await changeRender({id:job.id,projectId:job.projectId,type:"cancel",expectedRevision:state.revision});
 }
 const snapshot=structuredClone(fixture);for(const asset of snapshot.mediaAssets)asset.sourcePath=currentSource;
 await enqueueRender({id:"direct-export",projectId:"classic-project",sceneId:"main-scene",sourceRevision:5,snapshot,options,delivery:"direct",destinationName:"Direct.mp4"});
 expect(await claimRender("background-worker")).toBeNull();
 const job=await claimRender("direct-worker","direct-export");expect(job?.delivery).toBe("direct");
 const receipt=await reportRender({id:"direct-export",projectId:"classic-project",attempt:"direct-worker",progress:1,status:"completed",message:"Saved Direct.mp4"});
 expect(receipt.status).toBe("completed");expect((await readRenderJob("direct-export")).outputId).toBeNull();
});
EOF
classic/node_modules/.bin/prettier --write classic/apps/web/src/export/queue/server.test.ts > /tmp/projects-export-format.log
